        return;
    }
    char axis = 'X';
    float step = 10.0f;
    if (body != nullptr) {
        const char* pa = std::strstr(body, "\"axis\":\"");
        if (pa != nullptr) axis = pa[8];
        const char* ps = std::strstr(body, "\"step_mm\":");
        if (ps != nullptr) step = std::strtof(ps + 10, nullptr);
    }
    ui_gw_job_jog(axis, step);
    char buf[256];
    std::snprintf(buf, sizeof(buf), "{\"status\":\"ok\",\"axis\":\"%c\",\"step_mm\":%.2f}", axis, step);
    send_json_and_close(client, 200, buf);
}

